  fme = `Tắt`,
  pme = `Thấp`,
  mme = `Vừa`,
  hme = `Cao`,
  gme = `Âm thanh khởi động`,
  _me = `Âm thanh tắt máy`,
  vme = `Đèn LED chỉ ô người chơi`,
  yme = `Tắt`,
  bme = `Khi có nhiều tay cầm gắn vào`,
  xme = `Bật`,
  Sme = `Căn chỉnh gyro`,
  Cme = `Toàn bộ tốc độ pitch, yaw, và roll phải gần bằng không khi tay cầm nằm trên bề mặt cố định. Có thể gặp một chút độ nhiễu. Nếu có chỉ số bị lệch theo hướng nào đó, điều khiển sẽ "trôi" khi đang chơi. Hãy ấn "Căn chỉnh" để chỉnh sửa độ "trôi".`,
  wme = `Khi bật căn chỉnh tự động, độ trôi của gyro sẽ căn chỉnh lại khi có thể. Chuyển động quá mức sẽ đặt lại quá trình mỗi khi vượt ngưỡng mức độ chấp nhận. Điều chỉnh mức độ chấp nhận để quá trình tự động căn chỉnh không bao giờ lấp đầy hoàn toàn khi bạn đang cầm tay cầm - mà chỉ khi nằm trên bề mặt cố định.`,
  Tme = `Tiến độ căn chỉnh tự động`,
  Eme = `Tiến độ căn chỉnh gyro bị trôi`,
  Dme = `Căn chỉnh tự động: Mức độ chấp nhận căn chỉnh di chuyển`,
  Ome = `Vui lòng đặt tay cầm lên một bề mặt cố định và bằng phẳng trong 4 giây.`,
  kme = `Đang căn chỉnh...`,
  Ame = `Căn chỉnh hoàn tất`,
  jme = `Căn chỉnh bắt đầu trong %1$s giây.`,
  Mme = `Đang căn chỉnh tiếng ồn cảm biến cố định và hiệu chỉnh độ trôi...`,
  Nme = `Căn chỉnh thành công: Đã tìm thấy hiệu chỉnh độ trôi.`,
  Pme = `Hết thời gian căn chỉnh: Đã phát hiện độ rung cao. Loại bỏ nguồn gây nhiễu (vd: nhạc lớn, quạt bàn, tiếng ồn, v.v.) và thử lại.`,
  Fme = `Quá trình này đòi hỏi tay cầm phải nằm yên một chỗ.`,
  Ime = `Trước khi tiến hành, hãy đặt tay cầm trên một mặt phẳng cố định.`,
  Lme = `Căn chỉnh sau %1$s...`,
  Rme = `Đang tìm mức độ chấp nhận độ nhiễu`,
  zme = `Đang tìm độ trôi/lệch của gyro`,
  Bme = `Căn chỉnh gyro hoàn tất`,
  Vme = `Đã chỉnh sửa độ thả trôi Gyro và hiệu chuẩn mức độ chấp nhận của căn chỉnh tự động. Nếu hiện tượng thả trôi xuất hiện suốt thời gian chơi, hãy sử dụng thanh trượt mức độ chấp nhận, hoặc tắt tính năng tự động căn chỉnh.`,
  Hme = `Bật "Tự động căn chỉnh" để âm thầm chỉnh sửa độ trôi vào bất cứ khi nào tay cầm nằm trên bề mặt tĩnh. Nếu tính năng này gây trôi khi cầm tay cầm, hãy tắt nó đi, rồi căn chỉnh lại nếu cần.`,
