  wke = `Trò chơi chưa hợp chuẩn`,
  Tke = `Khi chơi trò chưa hợp chuẩn từ thư viện, bạn có thể cần điều chỉnh bố cục tay cầm để có trải nghiệm chơi tốt hơn với bảng điều khiển thiết bị của bạn.`,
  Eke = `Các mẫu mặc định hoạt động với hầu hết trò chơi, nhưng chúng tôi luôn khuyến khích xem qua bố cục tạo bởi cộng đồng trò chơi, để xem liệu người chơi khác đã đăng bố cục tùy chỉnh nào chưa.`,
  Dke = `Những trò chơi này có thể yêu cầu bạn ấn các phím và nút. Khi đó, bạn sẽ cần gán lệnh cho nhóm nút vật lý trên thiết bị.`,
  Oke = `Thậm chí khi trò chơi yêu cầu nhấn một nút có trên Deck, bạn sẽ cần gán lệnh trùng khớp.`,
  kke = `Thậm chí khi trò chơi yêu cầu nhấn một nút có trên <1></1>, bạn sẽ cần gán cho nó mệnh lệnh trùng khớp.`,
  Ake = `Thậm chí khi trò chơi yêu cầu bạn nhấn một nút có trên Deck, bố cục của bạn có thể gán một mệnh lệnh khác cho nút đó.`,
  jke = `Thậm chí khi trò chơi yêu cầu bạn nhấn một nút có trên <1></1>, bố cục của bạn có thể gán một mệnh lệnh khác cho nút đó.`,
  Mke = `F`,
  Nke = `Nút X`,
  Pke = `Một thao tác nên thường thực hiện là tìm đến thiết lập điều khiển trong trò chơi, nơi sẽ chứa danh sách tất cả mệnh lệnh mà trò chơi sử dụng.`,
  Fke = `Sau đó gán lệnh cho từng kiểu tương tác vật lý trên Deck. `,
  Ike = `Nhưng hãy luôn luôn kiểm tra các bố cục cộng đồng trước nhé - vài người chơi khác có thể đã tìm ra lời đáp.`,
