  tje = `Lấy tay cầm ra!`,
  nje = `Trò chơi này yêu cầu có tay cầm để chơi.`,
  rje = `<1></1> của bạn sẽ hoạt động tốt đó!`,
  ije = `Bạn chưa đăng ký tay cầm nào, nhưng bất kỳ tay cầm Xbox hoặc PlayStation nào cũng sẽ hoạt động tốt`,
  aje = `Lấy tay cầm và ngả lưng ra!`,
  oje = `Trò chơi này cần một tay cầm cho trải nghiệm tối ưu. Vì thế hãy lấy tay cầm Steam Controller, Xbox, hoặc bất cứ thiết bị nào nhìn như tay cầm có thể kết nối tới máy tính của bạn.`,
  sje = `Không hiện trên các trò chơi sau này`,
  cje = `Chọn tùy chọn này nếu trò chơi yêu cầu tương tác chuột điều khiển camera hoặc con trỏ.`,
  lje = `Chọn tùy chọn này nếu trò chơi yêu cầu tương tác cần trỏ điều khiển camera hoặc con trỏ.`,
  uje = `Chọn tùy chọn này nếu trò chơi sử dụng tương tác chuột để di chuyển con trỏ, hoặc điều khiển camera góc nhìn thứ nhất hoặc thứ ba.`,
  dje = `Chọn tùy chọn này nếu trò chơi sử dụng tương tác cần trỏ để di chuyển con trỏ hoặc điều khiển camera góc nhìn thứ nhất hoặc thứ ba. Làm thế sẽ cung cấp tương tác cần trỏ cho trò chơi, nhưng được diễn giải thành chuyển động trên bàn rê để mang lại cảm giác như đang sử dụng chuột.`,
  fje = `Menu tròn hiện các tùy chọn theo vòng tròn.`,
  pje = `Menu cảm ứng có thiết kế ô lưới để dễ dàng dùng với bàn rê.`,
  mje = `Menu hotbar là một menu tuyến tính được thiết kế để nhấp chọn.`,
