  Lje = `Sửa thời gian gán nhiều nút`,
  Rje = `Điều chỉnh thời gian`,
  zje = `Chức năng gán nhiều nút có minh họa trực quan và điều chỉnh được trong trang chỉnh sửa chuyên dụng.`,
  Bje = `Mở rộng`,
  Vje = `Đóng`,
  Hje = `%1$s (%2$s)`,
  Uje = `Thời gian gán nhiều nút`,
  Wje = `Mỗi thanh là một lệnh mà điều khiển này tạo ra, chỉ trong một lần nhấn. Thời gian theo mili giây. Di chuyển đầu nắm điểm đầu và cuối của thanh để thay đổi khi nào lệnh được triển khai và khi nào thì ngưng.`,
  Gje = `Dòng thời gian`,
  Kje = `Lệnh`,
  qje = `Ấn`,
  Jje = `Thả`,
  Yje = `Độ dài ấn nút mô phỏng`,
  Xje = `Ấn giữ trong bao lâu trong chế độ xem trước này. Các lệnh phản hồi theo thao tác thả nút sẽ đi cùng với nó.`,
  Zje = `%1$s mili giây`,
  Qje = `+%1$s mili giây`,
