  iMe = `Phải ấn ít nhất %1$s để lệnh này triển khai.`,
  aMe = `%1$s kích hoạt khi ấn nút này, và lệnh này được đặt để cho phép ngắt, vậy nên nó được bỏ qua.`,
  oMe = `Điều khiển này chỉ tạo ra một lệnh, vậy nên không có thời gian giữa các lệnh để thiết lập. Độ trễ của nó vẫn được liệt kê bên dưới.`,
  sMe = `Sắp xếp lại đầu vào theo thời gian bắt đầu`,
  cMe = `Sắp xếp`,
  lMe = `Gán nhiều nút chưa đặt tên`,
  uMe = `Gỡ gán nút`,
  dMe = `Chuột`,
  fMe = `Đang dùng`,
  pMe = `%1$s (%2$s)`,
  mMe = `Analog`,
  hMe = `Cò`,
  gMe = `Nút`,
  _Me = `Thêm điều khiển`,
  vMe = `Đổi điều khiển`,
  yMe = `Đổi lệnh`,
  bMe = `Gỡ điều khiển`,
