  SMe = `Thiết lập`,
  CMe = `Chọn một điều khiển cho %1$s`,
  wMe = `Chọn một chế độ cho %1$s`,
  TMe = `Gạt một cần trỏ ảo, dùng trực tiếp vị trí trên bàn rê của bạn để quyết định gạt đi bao xa.`,
  EMe = `Gạt một cần trỏ ảo, dùng trực tiếp vị trí gyro của bạn để quyết định gạt đi bao xa.`,
  DMe = `Di chuyển con trỏ chuột với tốc độ ổn định trong suốt thời gian gạt, gạt càng xa thì di chuyển càng nhanh.`,
  OMe = `Di chuyển con trỏ chuột như cách bạn di chuyển trên bàn rê, giống như bàn rê của laptop.`,
  kMe = `Chế độ chuột cần trỏ kiểu cũ, được giữ lại cho các thiết lập đã sử dụng từ trước.`,
  AMe = `Biến chuyển động của tay cầm thành chuyển động chuột, giúp bạn ngắm bằng cách nghiêng tay cầm.`,
  jMe = `Gửi tín hiệu cần trỏ camera, bạn đẩy càng xa thì camera xoay càng nhanh.`,
  MMe = `Biến chuyển động tay cầm thành tín hiệu cần trỏ camera, cho trò chơi đọc tín hiệu của cần trỏ thay vì chuột.`,
  NMe = `Biến chuyển động của tay cầm thành gạt cần trỏ, như thể bạn đang đẩy cần đó đi xa đến thế.`,
  PMe = `Gán bàn rê vào một khu vực của màn hình, để cho một điểm trên bàn rê luôn luôn chỉ vào cùng một nơi.`,
  FMe = `Gửi trực tiếp tới trò chơi góc độ của một camera, cho trò chơi hỗ trợ tính năng này, thay vì chuyển động chuột hay cần trỏ mà chế độ khác cung cấp.`,
  IMe = `Để cho điều khiển này không làm gì cả trong khi đây là lựa chọn.`,
  LMe = `Gửi đầu vào cần trỏ đến trò chơi, nhưng đọc chuyển động bàn rê của bạn giống như chuột. Dành cho trò chơi muốn dùng cần trỏ để nhắm mục tiêu hoặc di chuyển con trỏ.`,
  RMe = `Gửi đầu vào cần trỏ đến trò chơi, nhưng đọc chuyển động gyro của bạn giống như chuột. Dành cho trò chơi muốn dùng cần trỏ để nhắm mục tiêu hoặc di chuyển con trỏ.`,
