  WVe = `Cổng chữ thập`,
  GVe = `Vùng tương tác sẽ có hình chữ thập, ưu tiên các chuyển động theo phương đứng hoặc nằm, thay vì các hướng chéo.`,
  KVe = `Nhấp`,
  qVe = `Lệnh này sẽ được thực thi khi bạn nhấp bàn cảm ứng/cần trỏ. Nếu tùy chọn 'Yêu cầu nhấp' được bật, nhấp vào hướng của bàn cảm ứng sẽ đồng thời gửi lệnh điều hướng và lệnh này tới trò chơi.`,
  JVe = `Chạm`,
  YVe = `Lệnh này sẽ được thực thi khi chạm bàn cảm ứng/cần trỏ.`,
  XVe = `Vùng giao thoa`,
  ZVe = `Chỉ số vùng giao thoa quyết định khu vực kích hoạt cùng lúc hai hướng phím bốn chiều. Khi ở mức thấp nhất, vùng giao thoa gần như không tồn tại, và vì thế chỉ kích hoạt được đúng 4 chiều điều khiển. Khi ở mức cao nhất, vùng giao thoa gần như luôn hiện hữu, ấn ở vị trí nào cũng kích hoạt hai hướng cùng lúc, trừ phi bạn ấn ở vùng chữ thập.`,
  QVe = `Ghi đè cường độ haptic`,
  $Ve = `Chức năng này điều chỉnh cường độ của haptic. Tín hiệu haptic được kích hoạt khi bật/tắt tương tác.`,
