  FHe = `Lệnh này sẽ được thực thi khi bạn nhấn hướng phải trên DPad.`,
  IHe = `Lệnh D-Pad: Nút lên`,
  LHe = `Lệnh này sẽ được thực thi khi bạn nhấn hướng lên trên DPad.`,
  RHe = `Lệnh D-Pad: Nút xuống`,
  zHe = `Lệnh này sẽ được thực thi khi bạn nhấn hướng xuống trên DPad.`,
  BHe = `Giữ để lặp lại (Turbo)`,
  VHe = `Nếu bật, giữ bất kỳ hướng nào sẽ khiến nó tự lặp lại. Chức năng này thường được gọi là 'Chế độ Turbo'.`,
  HHe = `Giữ để lặp lại (Turbo) - Bật`,
  UHe = `Nếu bật, giữ bất kỳ hướng nào sẽ khiến nó tự lặp lại. Chức năng này thường được gọi là 'Chế độ Turbo'.`,
  WHe = `Giữ để lặp lại (Turbo) - Tắt`,
  GHe = `Nếu bật, giữ bất kỳ hướng nào sẽ khiến nó tự lặp lại. Chức năng này thường được gọi là 'Chế độ Turbo'.`,
  KHe = `Khoảng lặp`,
  qHe = `Khi chế độ Turbo được bật, thông số này quyết định tốc độ lặp lại. Kéo về bên phải để có tốc độ lặp lại cao hơn.`,
  JHe = `Thời gian xung nhịp giả lập analog`,
  YHe = `Tổng thời gian mà phím sẽ được ấn, diễn tả theo đơn vị mili giây. Ví dụ: Nếu đặt thời gian này 100ms, và phần trăm xung nhịp ấn là 25%. Tức cứ 25ms là phím được ấn, thả ra trong 75ms tiếp theo, rồi lại tiếp tục ấn trong 25ms. Như vậy tổng thời gian hành trình là 100ms.`,
  XHe = `% thời gian giả lập analog`,
  ZHe = `Phần trăm thời gian mà phím sẽ được ấn, dựa trên tổng thời gian xung nhịp được thiết lập ở bên trên. Ví dụ: Nếu đặt thời gian này 100ms, và phần trăm xung nhịp ấn là 25%. Tức cứ 25ms là phím được ấn, thả ra trong 75ms tiếp theo, rồi lại tiếp tục ấn trong 25ms. Như vậy tổng thời gian hành trình là 100ms.`,
  QHe = `Bán kính lệnh vòng ngoài`,
  $He = `Khi đi đến ngoài bán kính được quy định trên D-Pad, phím được gán tại đây sẽ gửi tín hiệu đi. Ví dụ, lệnh 'Chạy' hoặc 'Tăng tốc' có thể được gán vào chỗ này khi di chuyển tay ra rìa bàn cảm ứng. Thanh trượt này tượng trưng cho một bán kính mở rộng từ tâm ra, và thanh trượt sẽ chỉ định nơi mà bán kính vòng ngoài bắt đầu.`,
  eUe = `Lệnh vòng ngoài`,
  tUe = `Khi đi đến ngoài bán kính được quy định trên D-Pad, phím được gán tại đây sẽ gửi tín hiệu đi.  Ví dụ, lệnh 'Chạy' hoặc 'Tăng tốc' có thể được gán vào chỗ này khi giữ ở vùng rìa.`,
  nUe = `Đảo lệnh vòng ngoài`,
  rUe = `Khi được bật, lệnh này sẽ được chuyển đi khi tay ở bán kính bên trong thay vì bên ngoài. Ví dụ, 'Đi' hoặc 'Lén lút' có thể được gửi tín hiệu khi ở trong vùng nhất định.`,
  iUe = `Gán nút vòng trong - Bật`,
  aUe = `Nút gán vào đây sẽ được kích hoạt khi tay chạm vào bán kính gán lệnh vùng trong. Ví dụ, 'Đi' hay 'Lén lút' có thể được kích hoạt khi tay chạm vào bên trong vùng này.`,
  oUe = `Gán nút vòng trong - Tắt`,
  sUe = `Nút gán vào đây sẽ được kích hoạt khi tay chạm vào bán kính gán lệnh vùng ngoài. Ví dụ, 'Chạy' hay 'Tăng tốc' có thể được kích hoạt khi tay chạm vào bên ngoài vùng này.`,
  cUe = `Hành vi nút`,
  lUe = `Hành vi của nút tương tác gyro có thể được đảo lại. Nếu ở chế độ tắt, gyro sẽ tắt khi nhấn nút.`,
  uUe = `Hành vi nút cho Gyro - Bật`,
  dUe = `Nếu chọn chế độ này, gyro của thiết bị sẽ bật khi nhấn nút.`,
  fUe = `Hành vi nút cho Gyro - Tắt`,
  pUe = `Nếu chọn chế độ này, gyro của thiết bị sẽ tắt khi nhấn nút.`,
  mUe = `Hành vi nút cho Gyro - Đổi bật/tắt`,
  hUe = `Nếu chọn chế độ này, gyro của thiết bị sẽ chuyển trạng thái bật tắt khi nhấn nút.`,
