  _0e = `Tương tác gyro chỉ được bật khi nhấp cò phải (RT).`,
  v0e = `Nút kích hoạt Gyro - Cò trái (LT)`,
  y0e = `Tương tác gyro chỉ được bật khi nhấp cò trái (RT).`,
  b0e = `Nút kích hoạt Gyro - Chạm cần trái`,
  x0e = `Tương tác gyro chỉ được bật khi chạm cần trái.`,
  S0e = `Nút kích hoạt Gyro - Chạm cần phải`,
  C0e = `Tương tác gyro chỉ được bật khi chạm cần phải.`,
  w0e = `Nút kích hoạt Gyro - Chạm cần phải hoặc bàn rê phải`,
  T0e = `Tương tác gyro chỉ được bật khi chạm cần phải hoặc bàn rê phải.`,
  E0e = `Đảo trục nằm`,
  D0e = `Nếu được bật, di chuyển ngón tay sang bên trái bàn cảm ứng sẽ làm cần trỏ di chuyển sang bên phải và ngược lại. Hãy lưu ý rằng thiết lập trò chơi thường có sẵn thiết lập này, nên bạn cần đảm bảo hai thiết lập không triệt tiêu lẫn nhau.`,
  O0e = `Đảo trục nằm - Bật`,
  k0e = `Nếu được bật, di chuyển ngón tay sang bên trái bàn cảm ứng sẽ làm cần trỏ di chuyển sang bên phải và ngược lại. Hãy lưu ý rằng thiết lập trò chơi thường có sẵn thiết lập này, nên bạn cần đảm bảo hai thiết lập không triệt tiêu lẫn nhau.`,
  A0e = `Đảo trục nằm - Tắt`,
  j0e = `Trục nằm của cần trỏ sẽ hoạt động như thường, chuyển động sang phía bên trái bàn cảm ứng sẽ tương ứng với chuyển động sang phía bên trái của cần trỏ.`,
  M0e = `Đảo trục đứng`,
  N0e = `Nếu được bật, di chuyển ngón tay lên phía trên bàn cảm ứng sẽ làm cần trỏ di chuyển xuống dưới và ngược lại. Hãy lưu ý rằng thiết lập trò chơi thường có sẵn thiết lập này, nên bạn cần đảm bảo hai thiết lập không triệt tiêu lẫn nhau.`,
  P0e = `Đảo trục đứng - Bật`,
  F0e = `Nếu được bật, di chuyển ngón tay lên phía trên bàn cảm ứng sẽ làm cần trỏ di chuyển xuống dưới và ngược lại. Hãy lưu ý rằng thiết lập trò chơi thường có sẵn thiết lập này, nên bạn cần đảm bảo hai thiết lập không triệt tiêu lẫn nhau.`,
  I0e = `Đảo trục đứng - Tắt`,
  L0e = `Trục đứng của cần trỏ sẽ hoạt động như thường, chuyển động lên phía trên bàn cảm ứng sẽ tương ứng với chuyển động lên phía trên của cần trỏ.`,
  R0e = `Tương quan độ nhạy theo chiều dọc`,
  z0e = `Tỉ lệ độ nhạy theo chiều dọc quyết định chuyển động phương dọc như thế nào so với chiều ngang. Tại vị trí 50% thanh trượt thì tỉ lệ dọc ngang là như nhau, nếu ít hơn một nửa thì tốc độ chiều dọc sẽ chậm hơn chiều ngang và ngược lại.`,
  B0e = `Làm mượt cần trỏ`,
  V0e = `Làm mượt là chức năng giúp cần trỏ được giả lập trở lại trạng thái nghỉ như bị tác động bởi lò xo vật lý, thay vì bị trở lại vị trí cân bằng một cách đột ngột ngay khi tay ngừng chạm vào bàn cảm ứng.`,
  H0e = `Làm mượt cần trỏ - Bật`,
  U0e = `Làm mượt là chức năng giúp cần trỏ được giả lập trở lại trạng thái nghỉ như bị tác động bởi lò xo vật lý, thay vì bị trở lại vị trí cân bằng một cách đột ngột ngay khi tay ngừng chạm vào bàn cảm ứng.`,
  W0e = `Làm mượt cần trỏ - Tắt`,
  G0e = `Ngay lập tức trở về không khi dừng.`,
  K0e = `Độ nhạy chuột`,
  q0e = `Độ nhạy con trỏ chuột khi cần trỏ giả lập tương tác chuột.`,
  J0e = `Chống vùng chết`,
  Y0e = `Hầu hết các trò chơi tự quy định mới vùng chết cho tín hiệu tay cầm. Nếu sử dụng tay cầm và di chuyển cần trỏ một khoảng nhỏ mà không gửi đi tín hiệu nào, hay điều khiển gượng gạo, thì điều này có thể gây ra bởi vùng chết quy định bởi trò chơi. Bạn có thể sửa điều này bằng cách dùng tính năng chống vùng chết. Tính năng này giảm bớt vùng chết đi và đem lại kiểm soát chắc chắn hơn với vùng chết đã được giảm bớt. Chỉ số trên thanh trượt này càng cao, thì vùng chết này càng nhỏ. Lưu ý rằng nếu vùng chết biến mất hoàn toàn, thì chuyển động nhỏ nhất ở mọi vị trí đều gửi tín hiệu đi. Bạn có thể dùng Đệm ngăn chống-vùng-chết để tạo ra một diện tích nhỏ, nơi mà không có tín hiệu nào được gửi đi, kể cả khi khu vực chống vùng chết lớn hơn cả vùng chết của trò chơi.`,
  X0e = `Đệm ngăn chống-vùng-chết`,
  Z0e = `Đệm ngăn chống-vùng-chết sẽ tạo ra một vùng chết tuyệt đối mới cho tay cầm, không bị ảnh hưởng bởi tính năng chống vùng chết. Thông thường, cần trỏ tay cầm sẽ có một vùng chết rất nhỏ từ tâm đi ra. Khi tay cầm ở trong vùng chết này, sẽ không có tín hiệu nào được gửi đi. Khi sử dụng tính năng chống vùng chết ở mức cao nhất, cần trỏ sẽ không còn vùng chết nữa, và vì thể chuyển động nhỏ nhất có thể gửi đi tín hiệu không cần thiết. Đệm ngăn chống-vùng-chết sẽ tạo ra một diện tích vùng chết nhỏ, và luôn luôn hiện diện cho dù khu vực chống vùng chết được đẩy lên cao nhất.`,
  Q0e = `Hiện tùy chọn nâng cao cho vùng chết`,
  $0e = `Độ nhạy chuột`,
  e2e = `Chống vùng chết`,
  t2e = `Hầu hết các trò chơi tự quy định mới vùng chết cho tín hiệu tay cầm. Nếu sử dụng tay cầm và di chuyển cần trỏ một khoảng nhỏ mà không gửi đi tín hiệu nào, hay điều khiển gượng gạo, thì điều này có thể gây ra bởi vùng chết quy định bởi trò chơi. Bạn có thể sửa điều này bằng cách dùng tính năng chống vùng chết. Tính năng này giảm bớt vùng chết đi và đem lại kiểm soát chắc chắn hơn với vùng chết đã được giảm bớt. Chỉ số trên thanh trượt này càng cao, thì vùng chết này càng nhỏ. Lưu ý rằng nếu vùng chết biến mất hoàn toàn, thì chuyển động nhỏ nhất ở mọi vị trí đều gửi tín hiệu đi. Bạn có thể dùng Đệm ngăn chống-vùng-chết để tạo ra một diện tích nhỏ, nơi mà không có tín hiệu nào được gửi đi, kể cả khi khu vực chống vùng chết lớn hơn cả vùng chết của trò chơi.`,
  n2e = `Đệm ngăn chống-vùng-chết`,
  r2e = `Đệm ngăn chống-vùng-chết sẽ tạo ra một vùng chết tuyệt đối mới cho tay cầm, không bị ảnh hưởng bởi tính năng chống vùng chết. Thông thường, cần trỏ tay cầm sẽ có một vùng chết rất nhỏ từ tâm đi ra. Khi tay cầm ở trong vùng chết này, sẽ không có tín hiệu nào được gửi đi. Khi sử dụng tính năng chống vùng chết ở mức cao nhất, cần trỏ sẽ không còn vùng chết nữa, và vì thể chuyển động nhỏ nhất có thể gửi đi tín hiệu không cần thiết. Đệm ngăn chống-vùng-chết sẽ tạo ra một diện tích vùng chết nhỏ, và luôn luôn hiện diện cho dù khu vực chống vùng chết được đẩy lên cao nhất.`,
  i2e = `Nút kích hoạt Gyro`,
