  j2e = `Tương tác gyro chỉ được bật khi kéo nhẹ cò trái (LT).`,
  M2e = `Nút kích hoạt Gyro - Kéo nhẹ cò phải (RT)`,
  N2e = `Tương tác gyro chỉ được bật khi kéo nhẹ cò phải (RT).`,
  P2e = `Nút kích hoạt Gyro - A`,
  F2e = `Tương tác gyro chỉ được bật khi nhấn nút A.`,
  I2e = `Nút kích hoạt Gyro - B`,
