  Yrt = `Trục xoay của Gyro`,
  Xrt = `Để điều khiển di chuyển ngang của chuột, bạn có thể xoay tay cầm theo trục yaw hoặc roll của tay cầm.`,
  Zrt = `Trục xoay của Gyro - Yaw`,
  Qrt = `Để điều khiển chuyển động chiều ngang của chuột, xoay tay cầm theo trục yaw.`,
  $rt = `Trục xoay của Gyro - Roll`,
  eit = `Để điều khiển chuyển động chiều ngang của chuột, xoay tay cầm theo trục roll.`,
  tit = `Trục quay của Gyro - Yaw & Roll`,
