  Bft = `Di trỏ chuột khi kích hoạt`,
  Vft = `Khi kích hoạt, liệu con trỏ chuột có nên tự nhảy vào tâm của vùng không?`,
  Hft = `Di trỏ chuột đến trung tâm khu vực khi kích hoạt chế độ`,
  Uft = `Giữ nguyên vị trí chuột hiện tại`,
  Wft = `Di trỏ chuột khi hủy kích hoạt`,
  Gft = `Khi bạn ngừng tiếp xúc hoặc tắt chế độ chuyển, liệu chuột có nên nhảy về vị trí trước khi vào chế độ chuyển hay không?`,
  Kft = `Về vị trí: Bật`,
  qft = `Điều này sẽ khiến chuột về vị trí trước đó, khi rời tay khỏi bàn rê hoặc kết thúc chuyển chế độ.`,
  Jft = `Về vị trí: Tắt`,
