  Qmt = `Loại hoạt hóa`,
  $mt = `Hoạt hóa sẽ quyết định cách ấn nút tương tác như thế nào. Chúng ta có ấn thường, ấn giữ lâu, nhấn đúp v.v. Chọn cách hoạt hóa ở đây hoặc tháo bỏ.`,
  eht = `Không - Gỡ bỏ hoạt hóa`,
  tht = `Chọn mục này sẽ gỡ bỏ hoạt hóa và bất kỳ lệnh nào trong đó.`,
  nht = `Ấn thường`,
  rht = `Hoạt hóa ấn thường là chế độ mặc định. Khi bạn ấn nút, nó sẽ kích hoạt và giữ như thế cho đến khi nhả nút.`,
  iht = `Nhấn đúp`,
  aht = `Hoạt hóa nhấn đúp yêu cầu bạn phải nhấn đúp để kích hoạt. Nếu giữ phím khi ấn lần thứ hai, nó sẽ được giữ nguyên. Các hoạt hóa khác có khả năng xen giữa trên cùng một nút bấm sẽ không được kích hoạt nếu nhấn đúp đã được kích hoạt, và sẽ tạm ngưng cho đến khi thời gian chờ nhấn đúp trôi qua.`,
  oht = `Ấn giữ lâu`,
  sht = `Hoạt hóa ấn lâu cần phải giữ nút trong một khoảng thời gian. Khi thời gian giữ nút đã trôi qua, nó sẽ được giữ kích hoạt cho đến khi thả phím. Mọi hoạt hóa xen giữa khác trên cùng một nút bấm sẽ không được ưu tiên kích hoạt nếu hoạt hóa ấn giữ lâu đang được khai hỏa, và sẽ tạm ngưng cho đến khi nút được thả ra trong khoảng thời gian ấn giữ nút.`,
  cht = `Bắt đầu ấn`,
  lht = `'Hoạt hóa - Bắt đầu ấn' kích hoạt khi nút được ấn. Nó tự động tắt ngay kể cả khi nút đó vẫn được tiếp tục giữ. Điều này rất hữu dụng, đặc biệt khi dùng với 'Hoạt hóa - Thả nút ấn', để chuyển đổi giữa 'Bật/tắt' thành 'Giữ phím', ví dụ như lệnh bật/tắt nút ngồi.`,
  uht = `Thả nút ấn`,
  dht = `Hoạt hóa thả nút được kích hoạt và tắt khi một nút được thả ra.`,
  fht = `Ấn nhẹ`,
