  mht = `Analog`,
  hht = `Hoạt hóa analog tạo ra tín hiệu đầu ra analog.`,
  ght = `Nút hợp phím`,
  _ht = `Hợp phím và hoạt hóa được kích hoạt khi cả hai nút chức năng hoạt và hợp phím được ấn đồng thời.`,
  vht = `Mệnh lệnh`,
