  Fht = `Tính năng giữ trạng thái này sẽ khiến hoạt hóa tiếp tục hoạt động kể cả sau khi thả nút, và chỉ dừng khi nhấn lại.`,
  Iht = `Giữ trạng thái - Bật`,
  Lht = `Nút hoạt hóa này sẽ tiếp tục hoạt động kể ngay sau khi thả nút và chỉ dừng khi được kích hoạt lại.`,
  Rht = `Giữ trạng thái - Tắt`,
  zht = `Nút hoạt hóa này sẽ hoạt động như thông thường, chừng nào còn giữ nút, thì phím sẽ còn được kích hoạt.`,
  Bht = `Đảo tín hiệu vào`,
  Vht = `Đảo tín hiệu vào: Thả nút sẽ kích hoạt lệnh trong khi nhấn nút sẽ vô hiệu lệnh.`,
  Hht = `Có thể xen ngang`,
  Uht = `Các hoạt hóa có thể được xen ngang là loại có thể bị tạm dừng hoặc dừng hẳn bởi hoạt hóa khác, Ví dụ, hoạt hóa ấn lâu có thể chèn hoạt hóa ấn hết, thế nên hoạt hóa ấn hết chỉ được kích hoạt khi hoạt hóa ấn lâu hiện không được dùng. Nếu không thể xen ngang, thì các hoạt hóa ấn lâu này sẽ phớt lờ các hoạt hóa khác.`,
  Wht = `Có thể xen ngang - Bật`,
  Ght = `Hoạt hóa này sẽ tạm dừng hoặc không kích hoạt nếu các hoạt hóa khác đang hiệu lực. Ấn lâu, nhấp đúp, v.v. sẽ được ưu tiên trước hoạt hóa này và phải đến khi chúng được thỏa điều kiện thì hoạt hóa này mới được phép kích hoạt. Nếu các hoạt hóa kia đang được kích hoạt, thì hoạt hoá này sẽ không được dùng.`,
  Kht = `Có thể xen ngang - Tắt`,
  qht = `Hoạt hóa này sẽ phớt lờ các hoạt hóa khác và luôn luôn được bật/tắt như thể nó là hoạt hóa duy nhất.`,
  Jht = `Độ trễ bắt đầu ấn`,
  Yht = `Hoạt hóa này sẽ đợi một khoảng thời gian sau khi nút ấn thì mới kích hoạt. Độ trễ này sẽ bù lại cho cả khoảng thời gian mà nút được ấn. Nếu độ trễ kết thúc được đặt bằng không, thời gian hoãn kích hoạt nút sẽ tương ứng với thời gian nút được ấn, cộng thêm thời gian trễ.`,
  Xht = `Độ trễ kết thúc ấn`,
  Zht = `Hoạt hóa này sẽ đợi một khoảng thời gian sau khi nút được thả ra trước khi tắt. Độ trễ kết thúc sẽ làm cho một nút hoạt động lâu hơn tương tác ấn thực tế của người dùng.`,
  Qht = `Cường độ haptic`,
